export function filterMarkup(){return `<svg id="filter-svg" viewBox="0 0 900 620" aria-label="Aim the upper-left air nozzle and press left mouse to push debris into the lower-right waste chute"><defs><linearGradient id="filter-metal"><stop stop-color="#8d998b"/><stop offset=".35" stop-color="#374b42"/><stop offset=".7" stop-color="#738177"/><stop offset="1" stop-color="#23382e"/></linearGradient><linearGradient id="filter-collector-metal" gradientUnits="userSpaceOnUse" x1="0" y1="510" x2="0" y2="600"><stop stop-color="#8d998b"/><stop offset=".35" stop-color="#374b42"/><stop offset=".7" stop-color="#738177"/><stop offset="1" stop-color="#23382e"/></linearGradient><pattern id="filter-mesh" width="18" height="18" patternUnits="userSpaceOnUse"><path d="M0 0L18 18M18 0L0 18" stroke="#66786a" stroke-width="1"/></pattern><linearGradient id="filter-air"><stop stop-color="#d5e6cc" stop-opacity=".5"/><stop offset="1" stop-color="#d5e6cc" stop-opacity="0"/></linearGradient><clipPath id="filter-chamber"><rect x="80" y="90" width="740" height="510"/></clipPath></defs>
 <rect x="25" y="45" width="850" height="555" rx="8" fill="#283a31" stroke="url(#filter-metal)" stroke-width="15"/><rect x="80" y="90" width="740" height="430" fill="#15241c"/><rect x="85" y="95" width="730" height="420" fill="url(#filter-mesh)" opacity=".3"/><path d="M${CHAMBER.left-6} ${CHAMBER.floor}V${CHAMBER.top-6}H${CHAMBER.right+6}V${CHAMBER.bottom}" fill="none" stroke="url(#filter-metal)" stroke-width="12"/>
 ${BAFFLES.map(b=>`<path d="M${b.ax} ${b.ay}L${b.bx} ${b.by}" stroke="#101c15" stroke-width="18"/><path d="M${b.ax} ${b.ay}L${b.bx} ${b.by}" stroke="url(#filter-metal)" stroke-width="10" stroke-linecap="round"/>`).join('')}
 <path id="filter-hopper-opening" d="M${HOPPER.mouthLeft} ${HOPPER.mouthY}L${HOPPER.throatLeft} ${HOPPER.throatY}V${HOPPER.bottom}H${HOPPER.throatRight}V${HOPPER.throatY}L${HOPPER.mouthRight} ${HOPPER.mouthY}Z" fill="#0c1712"/>
 ${[FLOOR,...HOPPER_GUIDES,...HOPPER_WALLS].map((b,i)=>`<path data-collector-surface="${i}" d="M${b.ax} ${b.ay}L${b.bx} ${b.by}" fill="none" stroke="url(#filter-collector-metal)" stroke-width="${b.radius*2}" stroke-linecap="round"/>`).join('')}
 <path d="M${CHUTE.left+12} ${CHUTE.top+4}L${(CHUTE.left+CHUTE.right)/2} ${CHUTE.bottom-8}L${CHUTE.right-12} ${CHUTE.top+4}" fill="none" stroke="#b9c795" stroke-width="4"/>
 <g id="filter-suction" pointer-events="none" aria-label="Local extraction zone, 20 units above the 100-unit opening"><rect x="${SUCTION_ZONE.left}" y="${SUCTION_ZONE.top}" width="${SUCTION_ZONE.right-SUCTION_ZONE.left}" height="${SUCTION_ZONE.bottom-SUCTION_ZONE.top}" fill="#b2c2a3" opacity=".08"/><path d="M${SUCTION_ZONE.left} ${SUCTION_ZONE.bottom}V${SUCTION_ZONE.top}H${SUCTION_ZONE.right}" fill="none" stroke="#b2c2a3" stroke-opacity=".45" stroke-dasharray="3 4"/>
 ${[.25,.5,.75].map(f=>SUCTION_ZONE.left+(SUCTION_ZONE.right-SUCTION_ZONE.left)*f).map(x=>`<path d="M${x} ${SUCTION_ZONE.top+5}v9m-3-3l3 3l3-3" fill="none" stroke="#b2c2a3" stroke-opacity=".6" stroke-width="1.5"/>`).join('')}</g>
 <g id="filter-jet" clip-path="url(#filter-chamber)" pointer-events="none" opacity="0"><path id="filter-jet-shape" fill="url(#filter-air)"/></g><g id="filter-debris" clip-path="url(#filter-chamber)"></g>
 <g id="filter-aim" pointer-events="none" transform="translate(100 116)"><path d="M25 0H780" stroke="#b1c69c" stroke-width="1" stroke-dasharray="6 12" opacity=".35"/><path d="M0-10H42L58-5V5L42 10H0Z" fill="url(#filter-metal)" stroke="#cad4bd" stroke-width="2"/><path d="M6-14V14M16-14V14" stroke="#27372c" stroke-width="4"/></g><circle cx="100" cy="116" r="17" fill="#425547" stroke="#a8b398" stroke-width="3" pointer-events="none"/>
 <text x="185" y="75" fill="#c5ceb9" font-family="monospace" font-size="16">RECIRCULATION PREFILTER / AIM → FIRE</text><text x="735" y="613" fill="#c5ceb9" font-family="monospace" font-size="14">WASTE CHUTE</text>
 ${[[48,68],[852,68],[48,578],[852,578]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="7" fill="#b1b8a2"/><path d="M${x-4} ${y}h8" stroke="#26382c" stroke-width="2"/>`).join('')}<g id="filter-collection" pointer-events="none" opacity="0"><path d="M${CHUTE.left+10} ${CHUTE.top-9}L${(CHUTE.left+CHUTE.right)/2} ${CHUTE.bottom-10}L${CHUTE.right-10} ${CHUTE.top-9}" fill="none" stroke="#d6e5a8" stroke-width="8"/></g></svg>`;}
export const DEBRIS_PROFILES={light:'M-1-10L9-6L11 3L4 10L-9 5L-10-4Z',heavy:'M-15-10L-2-17L12-13L18-1L12 14L-4 17L-16 9Z',sticky:'M-10-11L5-14L13-5L10 8L0 13L-12 6L-14-3Z'};
export function debrisMarkup(debris){return debris.map(d=>`<g id="filter-object-${d.id}" transform="translate(${d.x} ${d.y})"><path d="${DEBRIS_PROFILES[d.type]}" fill="${d.type==='light'?'#a39b80':d.type==='heavy'?'#626758':'#6d7050'}" stroke="#c0bea2" stroke-width="1.3"/><path d="M-5-5L5 3M-3 6L7-4" fill="none" stroke="#333c2d" stroke-width="2"/>${d.attached?'<path d="M-16 0H16M0-16V16" stroke="#aaa16b" stroke-width="2" stroke-dasharray="3 4"/>':''}</g>`).join('');}
export function interpolateDebris(a,b,fraction,time=null){
 const previous=new Map(a.map(d=>[d.id,d])),latestIds=new Set(b.map(d=>d.id));
 const positions=b.map(d=>{if(d.capture&&time!==null)return {...d,...capturePosition(d,time)};const old=previous.get(d.id);return old?{...d,x:old.x+(d.x-old.x)*fraction,y:old.y+(d.y-old.y)*fraction}:{...d};});
 // Keep an authorised capture visible until the delayed presentation clock reaches
 // its endpoint, even if the newest server snapshot has already removed the body.
 if(time!==null)for(const d of a)if(d.capture&&!latestIds.has(d.id)&&time<d.capture.startedAt+SUCTION_ZONE.duration)positions.push({...d,...capturePosition(d,time)});
 return positions;
}
export function filterPoint(svg,e){const r=svg.getBoundingClientRect(),scale=Math.min(r.width/900,r.height/620);return{x:(e.clientX-r.left-(r.width-900*scale)/2)/scale,y:(e.clientY-r.top-(r.height-620*scale)/2)/scale};}
export function attachFilter({get,send,player,root=window,doc=document,now=()=>performance.now(),requestFrame=cb=>requestAnimationFrame(cb),cancelFrame=id=>cancelAnimationFrame(id),onFire=()=>{},onCollect=()=>{},onClear=()=>{}}){
 get('filter-board').innerHTML=filterMarkup();const svg=get('filter-svg'),presses=new Map(),pending=new Map();let state,online=false,frame=null,previous=null,latest=null,received=0,angle=.65,jetAngle=.65,jetUntil=0,collectionUntil=0;
 const enabled=()=>online&&state?.status==='running'&&state.stations.FILTER_BANK===player&&!doc.hidden;
 function aim(e){const p=filterPoint(svg,e);angle=Math.max(-.2,Math.min(Math.PI/2+.15,Math.atan2(p.y-NOZZLE.y,p.x-NOZZLE.x)));get('filter-aim').setAttribute('transform',`translate(100 116) rotate(${angle*180/Math.PI})`);}
 svg.addEventListener('pointermove',aim);
 svg.addEventListener('pointerdown',e=>{if(e.button!==0||!enabled()||presses.has(e.pointerId))return;const p=filterPoint(svg,e);if(p.x<CHAMBER.left||p.x>CHAMBER.right||p.y<CHAMBER.top||p.y>CHAMBER.floor)return;e.preventDefault();presses.set(e.pointerId,e.timeStamp);aim(e);const seq=send({type:'filter_shot',generation:state.filter.generation,angle});if(seq!==null){pending.set(seq,true);if(state.filter.reserve>=state.filter.cost){jetUntil=now()+160;jetAngle=angle;onFire();paint();}get('filter-hint').textContent='Pulse submitted';}});
 const release=e=>{if(e.timeStamp>=(presses.get(e.pointerId)??Infinity))presses.delete(e.pointerId);};root.addEventListener('pointerup',release,true);root.addEventListener('pointercancel',release,true);root.addEventListener('blur',()=>presses.clear());doc.addEventListener('visibilitychange',()=>{presses.clear();previous=null;received=now();if(doc.hidden&&frame!==null){cancelFrame(frame);frame=null;}});
 function paint(){if(!state)return;const f=state.filter,age=Math.max(0,(now()-received)/1000),target=Math.min(latest.elapsed,latest.elapsed-.1+age),fraction=previous&&latest.elapsed>previous.elapsed?Math.max(0,Math.min(1,(target-previous.elapsed)/(latest.elapsed-previous.elapsed))):1;
  const positions=state.status==='running'&&previous?interpolateDebris(previous.filter.debris,f.debris,fraction,target):f.debris;get('filter-debris').innerHTML=debrisMarkup(positions);
  get('filter-panel').setAttribute('data-phase',f.phase);
  get('filter-status').textContent=f.phase==='CLEAR'?'FILTER CLEAR':f.phase==='RELOADING'?'FILTER RELOADING — CLEANING REQUIRED':'FILTER RESTRICTED';
  get('filter-completion').textContent=f.phase==='CLEAR'?'CLEANING CYCLE COMPLETE · YOU CAN LEAVE THIS STATION':f.phase==='RELOADING'?'Expected debris accumulation. Return to clear the filter again.':'Clear the filter, then return when debris accumulates again.';
  get('filter-pressure-status').textContent=f.reserve+1e-9<f.cost?'INSUFFICIENT AIR PRESSURE — RECHARGING':`READY · ${f.cost} AIR PER PULSE`;
  get('filter-obstruction').textContent=`${Math.round(f.obstruction*100)}% OBSTRUCTED · ${f.debris.length} pieces`;get('filter-reserve').textContent=`AIR RESERVE ${Math.floor(f.reserve)} / ${f.capacity}`;get('filter-level').value=f.reserve;get('filter-level').max=f.capacity;get('filter-condition').value=f.obstruction*100;
  const jet=enabled()&&now()<jetUntil;get('filter-jet').setAttribute('opacity',jet?'1':'0');if(jet){const length=900*Math.min(1,(160-jetUntil+now())/60+.1),spread=12+length*Math.tan(JET_HALF_ANGLE),ux=Math.cos(jetAngle),uy=Math.sin(jetAngle);get('filter-jet-shape').setAttribute('d',`M100 116L${100+length*ux-spread*uy} ${116+length*uy+spread*ux}L${100+length*ux+spread*uy} ${116+length*uy-spread*ux}Z`);}
  get('filter-collection').setAttribute('opacity',enabled()&&now()<collectionUntil?'1':'0');
 }
 function tick(){frame=null;paint();if(enabled())frame=requestFrame(tick);}
 return {update(next){const fresh=!state||state.epoch!==next.epoch||state.filter.generation!==next.filter.generation||state.status!==next.status||!online;
  if(fresh){previous=null;presses.clear();pending.clear();jetUntil=0;}else if(latest&&next.elapsed>latest.elapsed)previous=latest;
  if(state&&state.epoch===next.epoch&&state.filter.generation===next.filter.generation){if(next.filter.cleared>state.filter.cleared){collectionUntil=now()+400;onCollect();}if(next.filter.cycle>state.filter.cycle)onClear();}
  if(fresh||!latest||next.elapsed>latest.elapsed)received=now();state=next;latest=next;online=true;paint();if(enabled()&&frame===null)frame=requestFrame(tick);if(!enabled()&&frame!==null){cancelFrame(frame);frame=null;}
 },onResult(r){if(!pending.has(r.seq))return;pending.delete(r.seq);if(r.status!=='accepted'){jetUntil=0;get('filter-hint').textContent=`${r.code}: ${r.message}`;}else get('filter-hint').textContent='Pulse applied — keep debris moving towards the chute';paint();},suspend(){online=false;presses.clear();pending.clear();previous=null;jetUntil=0;if(frame!==null)cancelFrame(frame);frame=null;paint();}};
}
